// SUP-4976
const doc = window.top.document;
const cookies = doc.querySelector('div#ot-sdk-btn-floating');

function adjustVideo() {
    const rootContainer = doc.querySelector('voltax-player#voltax-mp-video');
    if (rootContainer) {
        const stickyVideo = rootContainer.shadowRoot.querySelector('.voltax-mp-container-anchored');

        if (stickyVideo) {
            stickyVideo.style.setProperty('bottom', `150px`, 'important');
        }
    }
}

const observer = new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
        if (mutation.attributeName === 'style') {
            adjustVideo();
        }
    });
});

win.ggevents = win.ggevents || [];
win.ggevents.push({
    'inscreen.load': function (data) {
        if (GUMGUM.isad.container) {
            GUMGUM.isad.container.style.zIndex = 2147483645;

            const rootContainer = doc.querySelector('voltax-player#voltax-mp-video');
            if (rootContainer) {
                observer.observe(rootContainer, { attributes: true, attributeFilter: ['style'] });
                adjustVideo();
            }

        }
        if (cookies) {
            cookies.style.setProperty('bottom', `150px`, 'important');
        }
    },
    'inscreen.close': function (data) {
        observer.disconnect();
        if (cookies) {
            cookies.style.setProperty('bottom', `10px`, 'important');
        }
    }
});
